using System.Net;using Npgsql;using Xunit;
namespace BARANG.Core.IntegrationTests.Database;
#pragma warning disable CA1707,xUnit1051
[Collection(PostgreSqlDatabaseFixture.CollectionName)]public sealed class LogisticsFoundationTests(PostgreSqlDatabaseFixture database)
{
[Fact]public async Task Migration_creates_tables_permissions_sequences_rls_and_immutable_history(){await using NpgsqlConnection c=new(database.ConnectionString);await c.OpenAsync();await using NpgsqlCommand q=c.CreateCommand();q.CommandText="SELECT (SELECT count(*) FROM information_schema.tables WHERE table_schema='barang' AND table_name IN ('packages','package_items','shipping_handoffs','shipments','shipment_packages','shipment_status_history')),(SELECT count(*) FROM barang.permissions WHERE code IN ('logistics.read','packaging.manage','shipping.manage','delivery.manage')),(SELECT count(*) FROM pg_policies WHERE schemaname='barang' AND tablename IN ('packages','package_items','shipping_handoffs','shipments','shipment_packages','shipment_status_history')),(SELECT count(*) FROM pg_sequences WHERE schemaname='barang' AND sequencename IN ('package_number_seq','shipment_number_seq')),has_table_privilege(current_user,'barang.shipment_status_history','UPDATE'),has_table_privilege(current_user,'barang.shipment_status_history','DELETE')";await using NpgsqlDataReader r=await q.ExecuteReaderAsync();Assert.True(await r.ReadAsync());Assert.Equal(6,r.GetInt64(0));Assert.Equal(4,r.GetInt64(1));Assert.Equal(6,r.GetInt64(2));Assert.Equal(2,r.GetInt64(3));Assert.False(r.GetBoolean(4));Assert.False(r.GetBoolean(5));}
[Fact]public async Task Logistics_endpoints_require_authentication(){using PostgreSqlCoreApiFactory f=new(database.ConnectionString);using HttpClient c=f.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync($"/api/v1/logistics/packages/{Guid.NewGuid()}")).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync($"/api/v1/logistics/shipments/{Guid.NewGuid()}")).StatusCode);}
[Fact]public async Task Logistics_rls_hides_rows_without_company_context(){await using NpgsqlConnection c=new(database.ConnectionString);await c.OpenAsync();await using NpgsqlCommand clear=c.CreateCommand();clear.CommandText="RESET barang.company_id";await clear.ExecuteNonQueryAsync();await using NpgsqlCommand q=c.CreateCommand();q.CommandText="SELECT count(*) FROM barang.packages";Assert.Equal(0L,(long)(await q.ExecuteScalarAsync())!);}
}
#pragma warning restore CA1707,xUnit1051
